package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeFieldType;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneMidday;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class DateTimeFormatter_parseInto_TriageGen2Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;
    private Chronology mockChrono;
    private DateTimeZone mockZone;

    @Before
    public void setUp() {
        mockInstant = mock(ReadWritableInstant.class);
        mockParser = mock(DateTimeParser.class);
        mockChrono = mock(Chronology.class);
        mockZone = mock(DateTimeZone.class);

        // Default mock behaviors
        when(mockInstant.getMillis()).thenReturn(123456789L);
        when(mockInstant.getChronology()).thenReturn(mockChrono);
        when(mockChrono.getZone()).thenReturn(mockZone);
        when(mockZone.getOffset(anyLong())).thenReturn(0);

        // Setup a builder to create a real formatter instance with mocked parser
        // Since DateTimeFormatter constructor is not public/easily accessible with mocks, 
        // we use the Builder pattern which is the standard way to create it.
        formatter = new DateTimeFormatterBuilder()
                .append(mockParser)
                .toFormatter();
    }

    @Test(expected = IllegalArgumentException.class)
    public void parseInto_NullInstant_ThrowsException() {
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void parseInto_SuccessfulParse_ReturnsNewPosition() {
        String text = "2023-01-01";
        int position = 0;
        int expectedNewPos = 10;

        // Mock DateTimeParserBucket logic through the parser mock
        // Note: In real Joda, parser.parseInto interacts with the bucket.
        // Since we are testing the method logic in DateTimeFormatter, 
        // we must ensure the parser mock behaves correctly.
        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(position)))
                .thenReturn(expectedNewPos);

        // We need to mock the bucket's side effects if possible, but bucket is created inside.
        // However, we can mock the instant's setters to verify they are called.

        int actualPos = formatter.parseInto(mockInstant, text, position);

        assertEquals(expectedNewPos, actualPos);
        verify(mockInstant).setMillis(anyLong());
        verify(mockInstant).setChronology(any(Chronology.class));
    }

    @Test
    public void parseInto_WithOffsetParsed_UpdatesZone() {
        // Setup formatter with offset parsing enabled
        formatter = new DateTimeFormatterBuilder()
                .append(mockParser)
                .toFormatter()
                .withOffsetParsed();

        String text = "+02:00";
        int position = 0;

        // To test the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
        // This requires a real DateTimeParserBucket. Since we can't easily inject a 
        // mock bucket into the method (it's instantiated via 'new'), we rely on 
        // the parser mock to trigger the internal logic if possible.
        // In a real unit test for this complex internal logic, one might use PowerMock,
        // but here we will simulate the flow.

        // Because we cannot mock the 'new DateTimeParserBucket', we use a real parser 
        // that is known to work to exercise the branches.
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendOffset("+02:00", "Z")
                .appendPattern("yyyyMMdd")
                .toFormatter();

        ReadWritableInstant instant = new MutableDateTime(123456789L);
        int newPos = realFormatter.parseInto(instant, "20230101+02:00", 0);

        assertEquals(8, newPos);
        assertEquals(DateTimeZone.forOffsetHours(2), instant.getZone());
    }

    @Test
    public void parseInto_WithExplicitZone_SetsZone() {
        DateTimeZone targetZone = DateTimeZone.UTC;
        formatter = formatter.withZone(targetZone);

        String text = "20230101";
        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), anyInt()))
                .thenReturn(8);

        formatter.parseInto(mockInstant, text, 0);

        verify(mockInstant).setZone(targetZone);
    }

    @Test
    public void parseInto_WithPivotYear_UsesPivotYear() {
        int pivotYear = 2000;
        formatter = formatter.withPivotYear(pivotYear);

        String text = "230101"; // Assuming 2-digit year
        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), anyInt()))
                .thenReturn(6);

        formatter.parseInto(mockInstant, text, 0);

        // Verification of pivot year usage is implicit in the bucket creation
        // In a real scenario, we'd check if the parsed year matches the pivot logic.
    }

    @Test
    public void parseInto_WithLocale_UsesLocale() {
        Locale locale = Locale.FRENCH;
        formatter = formatter.withLocale(locale);

        String text = "2023-01-01";
        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), anyInt()))
                .thenReturn(10);

        formatter.parseInto(mockInstant, text, 0);

        assertEquals(locale, formatter.getLocale());
    }
}
